mapper.select:




SELECT DISTINCT
res.ID_ AS id,
res.NAME_ AS name,
def.NAME_ AS category,
def.KEY_ AS processDefinitionKey,
res.START_TIME_ AS createTime,
res.END_TIME_ AS endTime,
u.nickname AS startUserNickname,

/* 1. 获取来文单位 */
(SELECT var.TEXT_ FROM ACT_HI_VARINST var
WHERE var.PROC_INST_ID_ = res.ID_ AND var.NAME_ = #{VAR_SOURCE_UNIT} LIMIT 1) AS sourceUnit,

/* 2. 获取紧急程度 */
(SELECT var.TEXT_ FROM ACT_HI_VARINST var
WHERE var.PROC_INST_ID_ = res.ID_ AND var.NAME_ = #{VAR_URGENCY} LIMIT 1) AS urgencyDegree,

/* 3. 获取办结时限 (兼容 时间戳LONG_ 和 字符串TEXT_) */
(SELECT
CASE
/* 优先判断 LONG_ 是否有值 (时间戳存储) */
/* Kingbase: 毫秒转秒 -> 转timestamp -> 转字符串 */
WHEN var.LONG_ IS NOT NULL
THEN to_char(to_timestamp(var.LONG_ / 1000), 'YYYY-MM-DD HH24:MI:SS')
/* 否则取 TEXT_ (字符串存储) */
ELSE var.TEXT_
END
FROM ACT_HI_VARINST var
WHERE var.PROC_INST_ID_ = res.ID_ AND var.NAME_ = #{VAR_DEADLINE}
LIMIT 1
) AS deadlineDate,

/* 状态判断 */
(CASE WHEN res.END_TIME_ IS NOT NULL THEN 2 ELSE 1 END) AS status,

/* 当前环节 */
(SELECT string_agg(t.NAME_, ', ') FROM ACT_RU_TASK t
WHERE t.PROC_INST_ID_ = res.ID_) AS currTaskName,

/* 当前办理人 */
(SELECT string_agg(tu.nickname, ', ') FROM ACT_RU_TASK t
LEFT JOIN system_users tu ON t.ASSIGNEE_ = CAST(tu.id AS VARCHAR)
WHERE t.PROC_INST_ID_ = res.ID_) AS currTaskAssignee

FROM ACT_HI_PROCINST res
LEFT JOIN ACT_RE_PROCDEF def ON res.PROC_DEF_ID_ = def.ID_
LEFT JOIN system_users u ON res.START_USER_ID_ = CAST(u.id AS VARCHAR)
LEFT JOIN ACT_HI_TASKINST task ON res.ID_ = task.PROC_INST_ID_


    (res.START_USER_ID_ = CAST(#{userId} AS VARCHAR) OR task.ASSIGNEE_ = CAST(#{userId} AS VARCHAR))


        AND res.NAME_ LIKE CONCAT('%', #{reqVO.name}, '%')


        AND res.ID_ LIKE CONCAT('%', #{reqVO.processInstanceId}, '%')


        AND def.KEY_ = #{reqVO.processDefinitionKey}


        AND u.nickname LIKE CONCAT('%', #{reqVO.startUserNickname}, '%')


         AND res.END_TIME_ IS NULL 
         AND res.END_TIME_ IS NOT NULL 



        AND EXISTS (
        SELECT 1 FROM ACT_HI_VARINST v
        WHERE v.PROC_INST_ID_ = res.ID_
        AND v.NAME_ = #{VAR_SOURCE_UNIT}
        AND v.TEXT_ LIKE CONCAT('%', #{reqVO.startDeptName}, '%')
        )



        AND EXISTS (
        SELECT 1 FROM ACT_HI_VARINST v
        WHERE v.PROC_INST_ID_ = res.ID_
        AND v.NAME_ = #{VAR_DEADLINE}
        AND (
        /* 情况A: 时间戳 (LONG_) */
        (v.LONG_ IS NOT NULL AND (CURRENT_DATE - DATE(to_timestamp(v.LONG_ / 1000))) >= #{reqVO.overdueDays})
        OR
        /* 情况B: 字符串 (TEXT_) */
        (v.TEXT_ IS NOT NULL AND v.TEXT_ != '' AND (CURRENT_DATE - TO_DATE(v.TEXT_, 'YYYY-MM-DD')) >= #{reqVO.overdueDays})
        )
        )



        AND res.START_TIME_ BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}



ORDER BY res.START_TIME_ DESC

LIMIT #{reqVO.pageSize}
OFFSET (#{reqVO.pageNo} - 1) * #{reqVO.pageSize}
